def numDupDigitsAtMostN(n):
    s = str(n)
    k = len(s)

    def perm(m, t):
        r = 1
        for i in range(t):
            r *= (m - i)
        return r

    unique = 0
    for length in range(1, k):
        unique += 9 * perm(9, length - 1)
    seen = set()
    for i, ch in enumerate(s):
        d = int(ch)
        start = 1 if i == 0 else 0
        for x in range(start, d):
            if x not in seen:
                unique += perm(9 - i, k - 1 - i)
        if d in seen:
            break
        seen.add(d)
    else:
        unique += 1
    return n - unique
